function matchedBooks(){
 const q=$('#search').value.trim().toLowerCase();
 return sortedBooks(state.books.filter(b=>!b.archived&&(!collection||(b.collectionId||'general')===collection)).filter(b=>`${b.title} ${b.author} ${b.series||''} ${b.isbn} ${b.id} ${b.publisher} ${b.room||''} ${b.bookcase||''} ${b.shelf||''} ${state.borrowers.find(p=>p.id===activeLoan(state,b.id)?.borrowerId)?.name||''}`.toLowerCase().includes(q)&&(view!=='loans'||activeLoan(state,b.id))),$('#sort').value,$('#direction').value);
}
function paginate(items){
 const result=pageItems(items,page,Number($('#page-size').value));page=result.page;
 $('#pagination').innerHTML=`<button class="secondary" id="previous-page" ${page===1?'disabled':''}>Previous</button><span role="status">${result.start}–${result.end} of ${result.total} · Page ${page} of ${result.pages}</span><button class="secondary" id="next-page" ${page===result.pages?'disabled':''}>Next</button>`;
 $('#previous-page').onclick=()=>{page--;render();$('#content').scrollIntoView({block:'start'});};
 $('#next-page').onclick=()=>{page++;render();$('#content').scrollIntoView({block:'start'});};
 return result.items;
}
state={version:1,nextCopy:1,books:[],borrowers:[],loans:[]};
async function request(path,options={}){const response=await fetch(path,{...options,cache:'no-store',signal:AbortSignal.timeout(path.startsWith('/api/reminders')||path==='/api/accounts/delete'?45000:15000)});const data=await response.json();if(!response.ok)throw Object.assign(Error(data.error||'Server request failed.'),{status:response.status});return data;}
async function refresh(){try{let saved=await request('/api/state');if(!saved.state.libraryTheme){try{saved=await request('/api/action',{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"setLibraryTheme",input:{libraryTheme:$("#theme").value},revision:saved.revision})});}catch{saved=await request("/api/state");}}if(saved.revision>=revision){state=validateBackup(saved.state);revision=saved.revision;}stateReady=true;readOnly=false;render();}catch{readOnly=true;render();}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',5000);}
async function mutate(action,input){
 if(readOnly)throw Error('The library server is unavailable. Check that the Windows library service is running.');
 const name=typeof action==='string'?action:action.name;
 try{const saved=await request('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:name,input,revision})});state=validateBackup(saved.state);revision=saved.revision;render();return saved.result;}
 catch(e){if(e.status===409)await refresh();throw e.status?e:Error('Connection lost. Refresh and check whether your change was saved before trying again.');}
}
