 $('#bulk-bar').hidden=!['catalog','loans'].includes(view);$('#bulk-toggle').textContent=selecting?'Finish selecting':'Select books';for(const id of ['select-page','bulk-edit','clear-selection'])$('#'+id).hidden=!selecting;$('#bulk-edit').disabled=!selectedBooks.size||readOnly;$('#selection-count').textContent=selecting?`${selectedBooks.size} selected (maximum 500)`:'';
for(const id of ['checkout','return','share-list','share-qr'])$('#'+id).style.display=view==='reading'?'none':'';$('#collection').closest('.list-controls').style.display=view==='reading'?'none':'';const collections=state.collections||[{id:'general',name:'General'}];if(collection&&!collections.some(c=>c.id===collection))collection='';$('#collection').innerHTML='<option value="">All collections</option>'+collections.map(c=>`<option value="${escape(c.id)}">${escape(c.name)}</option>`).join('');$('#collection').value=collection;$("#requests").textContent="Requests ("+(state.requests||[]).filter(r=>["pending","approved"].includes(r.status)).length+")";const libraryName=state.libraryName||"Carribrary";const mark=document.querySelector('.mark');if(mark){mark.textContent='';if(state.libraryIcon192){const img=document.createElement('img');img.width=img.height=44;img.alt='';img.src='data:image/png;base64,'+state.libraryIcon192;mark.append(img);}else mark.textContent='▤';}$("#library-name").textContent=libraryName;document.title=libraryName;for(const [id,value]of [["banner-subtitle",state.bannerSubtitle??"A shelf worth sharing"],["encouraging-message",state.encouragingMessage??"A place for every book."]]){const element=document.getElementById(id);element.textContent=value;element.hidden=!value;}const copies=state.books.filter(b=>!b.archived&&(!collection||(b.collectionId||'general')===collection));const loans=state.loans.filter(l=>!l.returnedDate&&copies.some(b=>b.id===l.copyId));$('#stats').innerHTML=`<div class="stat"><strong>${copies.length}</strong><span>Physical copies</span></div><div class="stat"><strong>${loans.length}</strong><span>On loan</span></div><div class="stat"><strong>${copies.length-loans.length-(state.holds||[]).filter(h=>copies.some(b=>b.id===h.copyId)).length}</strong><span>Available</span></div>`;$('#save-status').textContent=readOnly?'Server unavailable · check connection':'Shared library on your home server';document.querySelectorAll('[data-view]').forEach(b=>{if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#search').placeholder=view==='borrowers'?'Search borrower name or contact':'Search title, author, series, ISBN or copy ID';$('#sort').disabled=view==='borrowers';$('#share-list').disabled=view==='borrowers';$('#share-qr').disabled=view==='reading';const q=$('#search').value.trim().toLowerCase();
