async function googleCoverSettings(){
 try{const status=await request('/api/cover-settings');
 openForm('Google Books covers',`<form><p>Optional third source, used when Open Library and Internet Archive find no cover.</p><p class="help">${status.configured?'An API key is saved (use Test saved key to verify it).':'No API key configured.'} The key stays on this server and is excluded from library exports.</p><p><a href="https://console.cloud.google.com/apis/library/books.googleapis.com" target="_blank" rel="noopener noreferrer">Enable Books API</a> · <a href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noopener noreferrer">Create an API key</a></p><button type="button" id="test-google-key" class="secondary">Test saved key</button><p class="help" id="google-key-status" role="status">Saving a key takes effect immediately. No restart is required.</p><label>New API key<input type="password" name="apiKey" autocomplete="off" maxlength="200" ${status.managedByEnvironment?'disabled':''}></label><p class="help">Restrict your key to the Books API. Leave the field blank and save to disable Google lookups. Existing covers keep their credit and links.</p>${errorHTML}<button type="submit" ${status.managedByEnvironment?'disabled':''}>Save key</button></form>`,async data=>{await request('/api/cover-settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});$('#form-dialog').close();toast(data.apiKey?'Google Books lookup enabled':'Google Books lookup disabled');});
 $('#test-google-key').onclick=async()=>{const button=$('#test-google-key'),note=$('#google-key-status');button.disabled=true;note.textContent='Checking the saved key…';try{const result=await request('/api/cover-settings/test',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});note.textContent=result.message;}catch(e){note.textContent=e.message;}finally{button.disabled=false;}};
 }catch(e){toast(e.message);}
}
