// Household reading profiles are private library data, separate from borrowers.
let readerSelection=preference('reader',''),readingFilter='tbr';
const readingLabels={want:'Want to read',reading:'Currently reading',finished:'Finished'};
function selectedReader(){const readers=state.readers||[];if(!readers.some(r=>r.id===readerSelection))readerSelection=readers[0]?.id||'';return readers.find(r=>r.id===readerSelection);}
function readerForm(existing=null){
 openForm(existing?'Rename reader':'Add household reader',`<form>${input('name','Reader name',existing?.name||'',true)}<input type="hidden" name="borrowerId" value=""><p class="help">Profiles organize household reading lists. Everyone with admin or paired-phone access can see them; these are not separate sign-ins.</p>${errorHTML}<button type="submit">Save reader</button></form>`,async data=>{const saved=await mutate(existing?'renameReader':'addReader',{...data,...(existing?{readerId:existing.id}:{})});readerSelection=saved.id;savePreference('reader',readerSelection);$('#form-dialog').close();render();});
 $('[name=name]').maxLength=80;
}
function renderReading(){
 const reader=selectedReader(),entries=(state.readingEntries||[]).filter(x=>x.readerId===readerSelection),q=$('#search').value.trim().toLocaleLowerCase();
 $('#search').placeholder='Search reading titles, authors or notes';$('#sort').disabled=false;$('#share-list').disabled=true;$('#share-qr').disabled=true;
 const rows=entries.map(entry=>({entry,book:state.books.find(b=>b.id===entry.copyId)})).filter(x=>x.book&&matchesReadingFilter(x.entry,readingFilter)&&`${x.book.title} ${x.book.author} ${x.entry.notes}`.toLocaleLowerCase().includes(q));
 const ranked=sortedBooks(rows.map(x=>x.book),$('#sort').value,$('#direction').value);const visible=paginate(ranked).map(book=>rows.find(x=>x.book.id===book.id));
 $('#stats').innerHTML=[[entries.filter(e=>e.status==='want'||e.status==='reading').length,'To Be Read'],[entries.filter(e=>e.status==='reading').length,'Currently reading'],[entries.filter(e=>e.status==='finished').length,'Finished']].map(([count,label])=>`<div class="stat"><strong>${count}</strong><span>${label}</span></div>`).join('');
 $('#content').innerHTML=`<section class="reader-workspace"><div class="toolbar reader-toolbar"><label>Reader<select id="reader-select">${(state.readers||[]).map(r=>`<option value="${escape(r.id)}">${escape(r.name)}${r.borrowerId?' (borrower)':''}</option>`).join('')}</select></label><button id="add-reader">Add reader</button>${reader?'<button class="secondary" id="rename-reader">Rename reader</button><button class="text danger" id="delete-reader">Delete reader</button><button class="secondary" id="personal-reading-share">Personal link / QR</button>':''}</div><p class="help">This admin view contains household-managed reading only. Borrower personal TBR, progress and notes are encrypted in their own account and are not visible here. Unread and currently reading books stay here until finished; reading history and loans are kept separately.</p>${reader?`<div class="list-controls"><label>Reading status<select id="reading-status"><option value="tbr">To Be Read (TBR)</option><option value="">All reading history</option>${Object.entries(readingLabels).map(([k,v])=>`<option value="${k}">${v} (${entries.filter(x=>x.status===k).length})</option>`).join('')}</select></label><button id="add-reading">Add book to TBR / reading list</button></div><div class="grid">${visible.map(({entry:e,book:b})=>`<article class="book"><div class="book-top">${b.coverUrl?`<img class="cover" src="${escape(b.coverUrl)}" alt="Cover of ${escape(b.title)}" loading="lazy" referrerpolicy="no-referrer">`:'<div class="cover cover-placeholder">▤</div>'}<div><span class="copy-id">${escape(b.id)}${b.archived?' · Removed from catalog':''}</span><h2>${escape(b.title)}</h2><div class="muted">${escape(b.author)}</div></div></div>${googleCredit(b.coverUrl)}<p><strong>${readingLabels[e.status]}</strong>${e.rating?` · ${'★'.repeat(e.rating)} (${e.rating}/5)`:''}</p><p class="muted">${e.startedDate?'Started '+date(e.startedDate):''}${e.startedDate&&e.finishedDate?'<br>':''}${e.finishedDate?'Finished '+date(e.finishedDate):''}</p>${e.notes?`<p class="reading-note">${escape(e.notes)}</p>`:''}<div class="record-actions">${e.status!=='finished'?`<button class="secondary" data-finish-reading="${escape(b.id)}">Mark as read</button>`:''}<button class="secondary" data-edit-reading="${escape(b.id)}">Edit reading entry</button><button class="text danger" data-remove-reading="${escape(b.id)}">Remove from reading list</button></div></article>`).join('')}</div>${!visible.length?'<div class="empty"><h2>No reading entries found</h2><p>Add a catalog book or change the status filter.</p></div>':''}`:'<div class="empty"><h2>Who is reading?</h2><p>Add a household reader to start their personal list.</p></div>'}</section>`;
 $('#reader-select').value=readerSelection;$('#reader-select').onchange=e=>{readerSelection=e.target.value;savePreference('reader',readerSelection);page=1;render();};$('#add-reader').onclick=()=>readerForm();
 if(!reader)return;$('#personal-reading-share').onclick=()=>personalReadingShare(reader.id);$('#reading-status').value=readingFilter;$('#reading-status').onchange=e=>{readingFilter=e.target.value;page=1;render();};$('#rename-reader').onclick=()=>readerForm(reader);$('#delete-reader').onclick=async()=>{if(!confirm(`Delete reader ${reader.name}? Remove their reading entries first. This does not delete catalog books.`))return;try{await mutate('removeReader',{readerId:reader.id});}catch(e){toast(e.message);}};$('#add-reading').onclick=()=>readingForm();
 document.querySelectorAll('[data-finish-reading]').forEach(b=>b.onclick=async()=>{const entry=entries.find(e=>e.copyId===b.dataset.finishReading);try{if(entry)await mutate('saveReading',{...finishReading(entry,today()),readerId:reader.id});}catch(e){toast(e.message);}});document.querySelectorAll('[data-edit-reading]').forEach(b=>b.onclick=()=>readingForm(b.dataset.editReading));document.querySelectorAll('[data-remove-reading]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this entry from the selected reader’s list? The catalog book stays.'))return;try{await mutate('removeReading',{readerId:reader.id,copyId:b.dataset.removeReading});}catch(e){toast(e.message);}});
}
function readingForm(copyId=''){
 const reader=selectedReader();if(!reader){readerForm();return;}
 const old=(state.readingEntries||[]).find(x=>x.readerId===reader.id&&x.copyId===copyId),books=sortedBooks(state.books.filter(b=>!b.archived||b.id===old?.copyId),'title');
 if(!books.length){toast('Add a catalog book first.');return;}
 openForm(`Reading · ${reader.name}`,`<form><label>Book<select name="copyId" required>${books.map(b=>`<option value="${escape(b.id)}" ${b.id===copyId?'selected':''}>${escape(b.title)} — ${escape(b.author)} · ${escape(b.id)}</option>`).join('')}</select></label><p class="help">Saving updates this reader’s entry for the chosen copy. Loan status stays unchanged.</p><label>Status<select name="status">${Object.entries(readingLabels).map(([k,v])=>`<option value="${k}" ${k===(old?.status||'want')?'selected':''}>${v}</option>`).join('')}</select></label>${input('startedDate','Started date (optional)',old?.startedDate||'',false,'date')}${input('finishedDate','Finished date (optional)',old?.finishedDate||'',false,'date')}<label>Rating<select name="rating"><option value="0">Unrated</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${n===old?.rating?'selected':''}>${n} ${n===1?'star':'stars'}</option>`).join('')}</select></label><label>Notes<textarea name="notes" maxlength="2000" rows="5">${escape(old?.notes||'')}</textarea></label>${errorHTML}<button type="submit">Save reading entry</button></form>`,async data=>{await mutate('saveReading',{...data,readerId:reader.id,rating:Number(data.rating)});$('#form-dialog').close();toast('Reading entry saved');});
 const form=$('#form-content form');function dates(fill=false){const status=form.elements.status.value;if(status==='want')form.elements.startedDate.value='';if(status!=='finished')form.elements.finishedDate.value='';if(fill&&status==='reading'&&!form.elements.startedDate.value)form.elements.startedDate.value=today();if(fill&&status==='finished'&&!form.elements.finishedDate.value)form.elements.finishedDate.value=today();form.elements.startedDate.disabled=status==='want';form.elements.finishedDate.disabled=status!=='finished';}
 form.elements.status.onchange=()=>dates(true);for(const name of ['startedDate','finishedDate'])form.elements[name].max=today();dates();
 form.elements.copyId.onchange=()=>readingForm(form.elements.copyId.value);
}
async function personalReadingShare(readerId){
 try{const status=await request(`/api/readers/${encodeURIComponent(readerId)}/sharing`);openForm('Personal reading link',`<form><p>This private link lets one reader update their reading and request books. Anyone holding it can use it. Send it only to that reader.</p>${status.url?'<div id="personal-qr"></div><label>Personal link<input id="personal-url" readonly></label><button type="button" id="copy-personal">Copy link</button><button type="button" id="replace-personal">Replace link / revoke old QR</button><button type="button" id="disable-personal">Revoke personal access</button>':status.configured?'<button type="button" id="enable-personal">Create personal link / QR</button>':'<p>Configure public HTTPS book-list sharing first. The server must be reachable for the reader to use this page.</p>'}${errorHTML}</form>`,async()=>{});
 const change=async action=>{try{await request(`/api/readers/${encodeURIComponent(readerId)}/sharing`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})});await personalReadingShare(readerId);}catch(e){$('#form-content .form-error').textContent=e.message;}};
 if(status.url){$('#personal-qr').innerHTML=qrSvg(status.url);$('#personal-url').value=status.url;$('#copy-personal').onclick=async()=>{try{await navigator.clipboard.writeText(status.url);toast('Private personal link copied');}catch{ $('#personal-url').select();toast('Select and copy the personal link');}};$('#replace-personal').onclick=()=>{if(confirm('Replace this reader’s link? Their old link and QR will immediately stop working.'))change('replace');};$('#disable-personal').onclick=()=>{if(confirm('Revoke this reader’s personal link? Their reading history stays.'))change('disable');};}else if(status.configured)$('#enable-personal').onclick=()=>change('enable');
 }catch(e){toast(e.message);}
}

$('#help-button').onclick=async()=>{try{const help=await request('help.json');openForm('Carribrary help',`<form><p><a href="quick-start.html" target="_blank" rel="noopener noreferrer">Illustrated quick start</a> · <a href="help.html" target="_blank" rel="noopener noreferrer">Open full server help page</a></p><input id="help-search" placeholder="Search help" aria-label="Search help"><div id="help-topics"></div>${errorHTML}</form>`,async()=>{});const show=()=>{const q=$('#help-search').value.toLocaleLowerCase();$('#help-topics').innerHTML=help.topics.filter(t=>(t.title+' '+t.body).toLocaleLowerCase().includes(q)).map(t=>`<details ${q?'open':''}><summary>${escape(t.title)}</summary><p>${escape(t.body)}</p></details>`).join('');};$('#help-search').oninput=show;show();}catch(e){toast('Help could not be loaded. Refresh the companion and try again, or reopen your library server.');}};
$('#accounts-button').onclick=()=>accountManagement();
async function accountManagement(){try{const {accounts}=await request('/api/accounts');openForm('Borrower accounts',`<form><p>Approve only after checking which existing borrower/profile belongs to this person. Accounts cannot discover old history from names or contacts alone.</p>${accounts.map(a=>`<article class="person"><h3>${escape(a.name)}</h3><p>@${escape(a.username)} · ${escape(a.status)} · ${escape(a.contact)}</p>${a.status!=='active'?`<label>Link account<select data-account-choice="${escape(a.id)}"><option value="">Create new reader and borrower</option>${(state.readers||[]).map(r=>{const removed=r.borrowerId&&!state.borrowers.some(b=>b.id===r.borrowerId&&!b.archived);return removed?`<option value="restore:${escape(r.id)}">Restore borrower for reader: ${escape(r.name)}</option><option value="replace:${escape(r.id)}">New borrower for reader: ${escape(r.name)}</option>`:`<option value="r:${escape(r.id)}">Reader: ${escape(r.name)}</option>`;}).join('')}${state.borrowers.filter(b=>!b.archived).map(b=>`<option value="b:${escape(b.id)}">Borrower: ${escape(b.name)}</option>`).join('')}</select></label><button type="button" data-account-approve="${escape(a.id)}">${a.status==='blocked'?'Unblock & approve':'Approve / activate'}</button>`:''}${a.status==='blocked'?`<button type="button" data-account-unblock="${escape(a.id)}">Unblock (review link next)</button><p class="help">If a linked borrower was removed, restore it or select a replacement above. Unblocking alone leaves approval pending.</p>`:''}${a.status!=='blocked'?`<button type="button" class="secondary danger" data-account-block="${escape(a.id)}">Block account</button><button type="button" data-account-reset="${escape(a.id)}">Reset password</button>`:''}<button type="button" class="secondary danger" data-account-delete="${escape(a.id)}">Delete account / personal information</button></article>`).join('')||'<p>No accounts yet. Visitors can sign up from the shared library page.</p>'}${errorHTML}</form>`,async()=>{});
 const action=async(name,input)=>{try{const saved=await request('/api/accounts/'+name,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});if(saved.snapshot){state=validateBackup(saved.snapshot.state);revision=saved.snapshot.revision;render();}if(name==='reset'){openForm('Private password reset link',`<form><p>This one-use link expires in 30 minutes. Give it privately to the account holder. Resetting the password signs out their previous sessions.</p><label>Reset link<input id="account-reset-url" readonly value="${escape(saved.url)}"></label><button type="button" id="copy-reset-link">Copy reset link</button>${errorHTML}</form>`,async()=>{});$('#copy-reset-link').onclick=async()=>{try{await navigator.clipboard.writeText(saved.url);toast('Private reset link copied');}catch{$('#account-reset-url').select();}};}else await accountManagement();}catch(e){$('#form-content .form-error').textContent=e.message;}};
 document.querySelectorAll('[data-account-delete]').forEach(b=>b.onclick=()=>accountDeletionForm(accounts.find(a=>a.id===b.dataset.accountDelete)));
 document.querySelectorAll('[data-account-approve]').forEach(b=>b.onclick=()=>{const id=b.dataset.accountApprove,choice=document.querySelector(`[data-account-choice="${id}"]`).value;if(confirm('Approve this person for the selected borrower’s lending records? If transferring a household reading profile, confirm its personal records belong to this person. Borrower private lists stay inaccessible to admins.'))action('approve',{accountId:id,readerId:/^(r|restore|replace):/.test(choice)?choice.slice(choice.indexOf(':')+1):'',borrowerId:choice.startsWith('b:')?choice.slice(2):'',restoreBorrower:choice.startsWith('restore:'),createBorrower:choice.startsWith('replace:')});});document.querySelectorAll('[data-account-unblock]').forEach(b=>b.onclick=()=>{if(confirm('Unblock this account? It will still need approval and a borrower/profile link. Old sessions and personal QR links stay revoked.'))action('unblock',{accountId:b.dataset.accountUnblock});});document.querySelectorAll('[data-account-block]').forEach(b=>b.onclick=()=>{if(confirm('Block this account, end all sign-ins and revoke its personal reading QR?'))action('block',{accountId:b.dataset.accountBlock});});document.querySelectorAll('[data-account-reset]').forEach(b=>b.onclick=()=>{if(confirm('Create a private, one-use password reset link?'))action('reset',{accountId:b.dataset.accountReset});});
}catch(e){toast(e.message);}}

$('#bulk-toggle').onclick=()=>{selecting=!selecting;if(!selecting)selectedBooks.clear();render();};
$('#clear-selection').onclick=()=>{selectedBooks.clear();render();};
$('#select-page').onclick=()=>{for(const b of pageItems(matchedBooks(),page,Number($('#page-size').value)).items){if(selectedBooks.size>=500)break;selectedBooks.add(b.id);}render();};
$('#bulk-edit').onclick=()=>{
 const ids=[...selectedBooks];if(!ids.length)return;const fields=[['collectionId','Collection'],['author','Author'],['publisher','Publisher'],['series','Series']];
 openForm(`Edit ${ids.length} selected books`,`<form><p>Only checked fields change. An empty text value clears that field. ISBNs, titles, copy numbers and loans stay as they are.</p>${fields.map(([key,label])=>`<label class="book-selection"><input type="checkbox" name="apply_${key}"> Change ${label}</label>${key==='collectionId'?`<label>New collection<select name="collectionId">${state.collections.map(c=>`<option value="${escape(c.id)}">${escape(c.name)}</option>`).join('')}</select></label>`:input(key,`New ${label}`)}`).join('')}<details><summary>Review selected books</summary><ul>${ids.map(id=>`<li>${escape(id)} · ${escape(state.books.find(b=>b.id===id)?.title)}</li>`).join('')}</ul></details>${errorHTML}<button type="submit">Review changes</button></form>`,async data=>{
  const changes=Object.fromEntries(fields.filter(([key])=>data['apply_'+key]==='on').map(([key])=>[key,data[key]]));if(!Object.keys(changes).length)throw Error('Check at least one field to change.');
  if(!confirm(`Update ${ids.length} books?\n\n`+Object.entries(changes).map(([k,v])=>`${k}: ${k==='collectionId'?state.collections.find(c=>c.id===v)?.name:v||'(clear field)'}`).join('\n')))return;
  await mutate('bulkEditBooks',{copyIds:ids,changes});selectedBooks.clear();selecting=false;render();$('#form-dialog').close();toast('Selected books updated');
 });
};
$('#recycle-bin').onclick=()=>recycleBin();
async function recycleBin(){await refresh();openForm('Recycle Bin',`<form><p>Restore deleted books and borrowers. Reused catalog numbers receive a free replacement number on restore. Removing a recovery entry is permanent; records needed for loan/reading history stay archived.</p>${(state.recycleBin||[]).slice().reverse().map(r=>`<article class="person"><strong>${escape(r.book?.title||r.borrower?.name)}</strong><p>${escape(r.book?.id||r.borrower?.id)} · ${escape(r.deletedAt.slice(0,10))} · ${r.book?'Book':'Borrower'}</p><button type="button" data-restore-deleted="${escape(r.id)}">Restore</button><button type="button" class="secondary danger" data-purge-deleted="${escape(r.id)}">Delete permanently</button></article>`).join('')||'<p>The Recycle Bin is empty.</p>'}${errorHTML}</form>`,async()=>{});
 const change=async(action,id)=>{try{const saved=await mutate(action,{deletedId:id});if(saved.restored)toast(saved.id===saved.previousId?'Record restored':`Restored as ${saved.id}; old number ${saved.previousId} was reused`);await recycleBin();}catch(e){$('#form-content .form-error').textContent=e.message;}};
 document.querySelectorAll('[data-restore-deleted]').forEach(b=>b.onclick=()=>change('restoreDeleted',b.dataset.restoreDeleted));document.querySelectorAll('[data-purge-deleted]').forEach(b=>b.onclick=()=>{if(confirm('Permanently remove this recovery entry? You cannot restore it from the Recycle Bin afterward.'))change('purgeDeleted',b.dataset.purgeDeleted);});
}
$('#reminders').onclick=()=>reminderSettings();
async function reminderSettings(){try{const c=await request('/api/reminders');openForm('Automatic email reminders',`<form><p>Use your email provider’s SMTP STARTTLS settings and an app password. Passwords stay encrypted on this server and are excluded from library exports.</p><label class="book-selection"><input type="checkbox" name="enabled" ${c.enabled?'checked':''}> Enable automatic reminders</label><label class="book-selection"><input type="checkbox" name="emailPasswordRecovery" ${c.emailPasswordRecovery?'checked':''}> Enable borrower email password recovery</label>${input('host','SMTP host',c.host)}${input('port','STARTTLS port (usually 587; not 465)',c.port,false,'number')}${input('username','SMTP username',c.username)}<label>App password ${c.passwordSaved?'(saved; leave blank to keep)':''}<input type="password" name="password" autocomplete="new-password"></label>${input('fromEmail','Sending email address',c.fromEmail,false,'email')}${input('daysBefore','Days before due (1–14)',c.daysBefore,false,'number')}${input('overdueDays','Days overdue (1–30)',c.overdueDays,false,'number')}${input('sendHour','Start hour (0–23, server time)',c.sendHour,false,'number')}<p class="help">Time zone: ${escape(c.timeZone)}. One message before due, on the due date, and once overdue. Checks every 15 minutes while the server runs. Only borrowers with an email and recorded permission receive reminders. Returned books are excluded.</p>${errorHTML}<button type="submit">Save reminder settings</button><button class="secondary" type="button" id="test-reminders">Send test to sending email</button><p id="reminder-test-status" role="status"></p><details><summary>Recent delivery attempts</summary>${c.history.map(h=>`<p>${escape(h.copyId)} · ${escape(h.stage)} · Due ${escape(h.dueDate)} · ${escape(h.status)} · ${escape(h.attemptedAt.slice(0,16))}</p>`).join('')||'<p>No attempts yet.</p>'}<p>“Sent” means accepted by your email provider. “Check-delivery” may be a failure or an interrupted send: check the mailbox before sending manually. Uncertain deliveries are not retried automatically.</p></details></form>`,async data=>{const saved={...data,enabled:data.enabled==='on',emailPasswordRecovery:data.emailPasswordRecovery==='on',port:Number(data.port),daysBefore:Number(data.daysBefore),overdueDays:Number(data.overdueDays),sendHour:Number(data.sendHour),password:data.password||null};await request('/api/reminders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(saved)});await reminderSettings();toast('Reminder settings saved');});$('#test-reminders').onclick=async()=>{if(!confirm('Send one test email using the saved settings to the sending email address?'))return;$('#test-reminders').disabled=true;try{await request('/api/reminders/test',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});$('#reminder-test-status').textContent='Test accepted by the email provider. Check the inbox and spam folder.';}catch(e){$('#reminder-test-status').textContent=e.message;}finally{if($('#test-reminders'))$('#test-reminders').disabled=false;}};}catch(e){toast(e.message);}}
$('#setup').onclick=()=>setupChecklist();
async function setupChecklist(){try{const c=await request('/api/setup');openForm('Setup & updates',`<form><p><strong>Carribrary ${escape(c.version)}</strong> · ${escape(c.platform)}</p><h3>1. Library and backups</h3><p>${c.books} active books · ${c.borrowers} active borrowers</p><p>Private data: <code>${escape(c.dataDirectory)}</code></p><p>Automatic encrypted library backups: ${c.backupCount}. Latest: ${escape(c.latestBackup||'Not created yet')}.</p><h3>2. Pair the household phones</h3><p>${c.pairedPhones} approved phone(s). Pairing is for household administrators. Friends use the separate shared-library QR.</p><p>Saved phone address: <code>${escape(c.remoteAddress||'Not configured')}</code></p><p>Local phone addresses: ${c.localAddresses.map(a=>`<code>${escape(a)}</code>`).join(', ')||'No LAN address detected'}.</p><button class="secondary" type="button" id="setup-pair">Open phone pairing</button><h3>3. Access away from home</h3><p>${escape(c.remoteInstructions)}</p><p>Reserve this server’s LAN address in your router. Forward TCP ${c.phonePort} to the same port for paired phones. For public sharing and borrower sign-in, forward TCP 80/443 to the HTTPS proxy. Never forward admin ${c.adminPort}, internal catalog ${c.catalogPort}, or discovery ${c.discoveryPort}.</p><p>Public browser address: <code>${escape(c.publicOrigin||'Not configured')}</code></p><p>Check from a phone with Wi-Fi OFF. A local check cannot prove that router forwarding or your ISP allows incoming connections.</p><button class="secondary" type="button" id="check-dns">Check saved hostname DNS</button><p id="dns-result" role="status"></p><h3>4. Update safely</h3><ol><li>Export a library backup before installing.</li><li>${escape(c.updateInstructions)}</li><li>Install the new Android APK over the existing app, keeping its data. Refresh the server browser.</li></ol><p>Keep the same installation and data directory. Do not uninstall to update. Existing pairings and settings are retained. Installers remain manual downloads; this app does not have an official update feed yet.</p><button class="secondary" type="button" id="setup-backup">Export library backup</button><p><a href="help.html" target="_blank" rel="noopener noreferrer">Full setup, update and troubleshooting guide</a></p>${errorHTML}</form>`,async()=>{});$('#setup-pair').onclick=()=>$('#devices').click();$('#setup-backup').onclick=()=>$('#export').click();$('#check-dns').onclick=async()=>{const b=$('#check-dns');b.disabled=true;try{const r=await request('/api/setup/dns',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});$('#dns-result').textContent=r.message;}catch(e){$('#dns-result').textContent=e.message;}finally{b.disabled=false;}};}catch(e){toast(e.message);}}

if(new URL(location.href).searchParams.get('setup')==='1')refresh().then(setupChecklist);

function accountDeletionForm(account){
 const requestDeletion=(action,input)=>request('/api/accounts/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});
 const selection={accountId:account.id,deleteInformation:false,readerId:'',borrowerId:'',guestRequestIds:[],removeBackups:false};
 openForm('Delete borrower account',`<form><p><strong>@${escape(account.username)} · ${escape(account.name)}</strong></p><label>What should be deleted?<select name="deletionScope"><option value="account">Sign-in account and private list — keep lending records</option><option value="information">Account and linked personal information — permanent</option></select></label><div id="delete-extra" hidden><p>Also include a reading profile or borrower only if it belongs to this person. Useful for unlinked/pending accounts. Linked records are included automatically.</p><label>Additional reading profile<select name="deleteReader"><option value="">No additional profile</option>${(state.readers||[]).map(r=>`<option value="${escape(r.id)}">${escape(r.name)}</option>`).join('')}</select></label><label>Additional borrower<select name="deleteBorrower"><option value="">No additional borrower</option>${state.borrowers.map(b=>`<option value="${escape(b.id)}">${escape(b.name)} · ${escape(b.id)}${b.archived?' (removed)':''}</option>`).join('')}</select></label><label class="book-selection"><input type="checkbox" name="removeBackups"> Also delete ALL stored automatic library backups and Windows pre-update safety ZIPs for this installation (affects the whole library)</label></div><p>Both scopes permanently delete the encrypted private list and end sign-in access. Export an encrypted personal backup first if wanted. Books stay in the catalog. Full information deletion cannot be undone through the Recycle Bin. Return active loans before deleting personal information; account-only deletion can keep those loans.</p><p>Exported backups, emails, and offline devices can retain older information. Refresh paired devices. Stored backup deletion cannot recall copies elsewhere or securely erase external storage. Administrator-protected Windows recovery points are removed separately in Update and recovery.</p>${errorHTML}<button type="submit" class="secondary">Preview deletion</button><button type="button" class="text" id="cancel-account-delete">Cancel</button></form>`,async data=>{
  selection.deleteInformation=data.deletionScope==='information';selection.readerId=selection.deleteInformation?data.deleteReader:'';selection.borrowerId=selection.deleteInformation?data.deleteBorrower:'';selection.removeBackups=selection.deleteInformation&&data.removeBackups==='on';await preview();
 });$('[name=deletionScope]').onchange=()=>$('#delete-extra').hidden=$('[name=deletionScope]').value!=='information';$('#cancel-account-delete').onclick=()=>accountManagement();
 async function preview(){const p=await requestDeletion('deletion-preview',selection);openForm('Review account deletion',`<form><p><strong>@${escape(p.username)}</strong> · ${selection.deleteInformation?'Account and selected personal information':'Sign-in account and private list; lending records stay'}</p>${selection.deleteInformation?`<p>Borrowers: ${p.borrowers.map(b=>escape(b.name)+' · '+escape(b.id)).join(', ')||'None linked/selected'}<br>Readers: ${p.readers.map(r=>escape(r.name)).join(', ')||'None linked/selected'}</p><ul><li>Private personal vault/content is not visible; account deletion removes its current encrypted vault.</li><li>${p.requests} requests</li><li>${p.returnedLoans} returned-loan records</li><li>${p.holds||0} associated holds released</li><li>${p.recoveryEntries} borrower recovery entries</li></ul>${p.activeLoans?`<p class="form-error">Return ${p.activeLoans} active loan(s) before deleting personal information.</p>`:''}${p.guestRequests.length?`<details open><summary>Other guest requests with matching contact details — select only this person’s</summary><p>Shared contact information does not prove ownership. These requests are kept unless selected.</p>${p.guestRequests.map(r=>`<label class="book-selection"><input type="checkbox" data-delete-guest="${escape(r.id)}" ${selection.guestRequestIds.includes(r.id)?'checked':''}> ${escape(r.name)} · ${escape(r.contact)} · ${escape(r.title)} · ${escape(r.status)}</label>`).join('')}<button type="button" class="secondary" id="review-delete-guests">Update preview</button></details>`:''}<p>${selection.removeBackups?`Delete ALL ${p.storedBackups} stored automatic/safety backups for the entire installation.`:`Keep ${p.storedBackups} stored automatic/safety backups; older information can remain in them.`}</p>`:'<p>Operational borrower, loan and request records remain. The account’s encrypted personal vault is deleted; export it first if wanted.</p>'}<label>Type username <strong>${escape(p.username)}</strong> to confirm<input name="confirmUsername" required autocomplete="off" spellcheck="false"></label>${errorHTML}<button type="submit" class="danger-fill" ${p.activeLoans?'disabled':''}>Delete permanently</button><button type="button" class="secondary" id="cancel-final-account-delete">Cancel</button></form>`,async data=>{
   const result=await requestDeletion('delete',{...selection,previewToken:p.previewToken,confirmation:data.confirmUsername});state=validateBackup(result.snapshot.state);revision=result.snapshot.revision;render();if(result.warnings?.length)alert('Account deleted. '+result.warnings.join(' '));await accountManagement();toast(result.informationDeleted?'Account and selected personal information deleted':'Sign-in account deleted; borrower/history kept');
  });$('#cancel-final-account-delete').onclick=()=>accountManagement();const guests=document.querySelectorAll('[data-delete-guest]');guests.forEach(box=>box.onchange=()=>{const submit=$('#form-content [type=submit]');submit.disabled=true;$('#review-delete-guests').textContent='Update preview before deleting';});if($('#review-delete-guests'))$('#review-delete-guests').onclick=async()=>{selection.guestRequestIds=[...guests].filter(box=>box.checked).map(box=>box.dataset.deleteGuest);try{await preview();}catch(e){$('#form-content .form-error').textContent=e.message;}};
 }
}

