async function notificationOverview(){try{const p=await request('/api/push-status');openForm('Optional PWA notifications',`<form><p>Borrower devices: ${p.borrowerDevices} · Librarian devices: ${p.adminDevices}</p><p>Borrowers enable reminders after sign-in. iPhone librarians enable new-request notifications inside their paired Home-screen companion. Server checks every minute. Email reminders remain independent. No titles or private borrower details are sent in push messages.</p>${p.history.map(h=>`<p>${escape(h.role)} · ${escape(h.lastStatus)}</p>`).join('')}<p class="form-error"></p></form>`,async()=>{});}catch(error){toast(error.message);}}
