// Server-authoritative holds and atomic batch circulation. All scan matching uses
// the existing ISBN/copy-ID/manual resolver; custom labels remain optional.
let lendingTab='holds',batchCopies=[];
async function lendingTools(tab='holds'){
 lendingTab=tab;await refresh();if(readOnly){toast('Reconnect before managing lending.');return;}
 const nav='<nav class="workspace-tabs" aria-label="Lending views">'+[['holds','Holds'],['checkout','Batch checkout'],['return','Batch return'],['limits','Lending limits']].map(([id,label])=>`<button type="button" class="secondary" data-lending-tab="${id}" ${tab===id?'aria-current="page"':''}>${label}</button>`).join('')+'</nav>';
 const people=state.borrowers.filter(b=>!b.archived),personOptions='<option value="">Choose borrower</option>'+people.map(p=>`<option value="${escape(p.id)}">${escape(p.name)}</option>`).join('');
 let body='';
 if(tab==='holds')body=`<p>Holds do not start loans or due dates. Release a hold to make the copy available again.</p><div id="hold-list">${(state.holds||[]).map(h=>{const book=state.books.find(b=>b.id===h.copyId),r=state.requests.find(r=>r.id===h.requestId),person=people.find(p=>p.id===h.borrowerId);return `<article class="person"><strong>${escape(book?.title||h.copyId)}</strong><p>${escape([book?.room,book?.bookcase,book?.shelf].filter(Boolean).join(" · "))}</p><p>${escape(h.copyId)} · ${escape(r?.name||person?.name||'Borrower')} · ${escape(h.stage)}</p>${h.stage==='pending'?'<p>Approve this request in Requests first.</p>':`<button type="button" data-hold-ready="${escape(h.id)}">Ready for pickup / delivery</button><button type="button" data-hold-handover="${escape(h.id)}">Confirm handover</button>`}<button type="button" class="secondary" data-hold-release="${escape(h.id)}">Release hold</button></article>`;}).join('')||'<p>No active holds.</p>'}</div><h3>Hold a copy for someone</h3><label>Available physical copy<select name="copyId" required><option value="">Choose copy</option>${state.books.filter(b=>!b.archived&&!activeLoan(state,b.id)&&!(state.holds||[]).some(h=>h.copyId===b.id)).sort((a,b)=>a.title.localeCompare(b.title)).map(b=>`<option value="${escape(b.id)}">${escape(b.id)} · ${escape(b.title)}</option>`).join('')}</select></label><label>Borrower<select name="borrowerId" required>${personOptions}</select></label><button type="submit">Create hold</button>`;
 else if(tab==='limits')body=`<p>Checkout batches and active loans are separate limits. Existing loans are kept when reducing a limit. Returns are never limited by these settings.</p>${input('maxBatchCheckout','Maximum books per checkout batch',state.maxBatchCheckout||5,true,'number')}${input('maxActiveLoans','Maximum active loans per borrower',state.maxActiveLoans||5,true,'number')}<button type="submit">Save lending limits</button>`;
 else body=`<p>${tab==='checkout'?`Select up to ${state.maxBatchCheckout||5} available physical copies for one borrower. Confirm handover before checkout. Held books are handed over from Holds / Requests.`:'Scan or search checked-out copies. Returns have no borrowing limit.'} Each batch saves together; if any copy conflicts, nothing in the batch changes.</p><div class="field-row">${input('batchSearch','ISBN / EAN, copy ID, title or author')}<button type="button" id="batch-scan" class="secondary">Scan</button></div><div id="batch-matches"></div><h3>Review selected books</h3><div id="batch-selected"></div>${tab==='checkout'?`<label>Borrower<select name="borrowerId" required>${personOptions}</select></label>${input('checkoutDate','Handover date',today(),true,'date')}${input('dueDate','Due date (optional)','','','date')}<label><input type="checkbox" name="handoverConfirmed" required> The borrower has received these books.</label>`:''}<button type="submit" id="batch-confirm">${tab==='checkout'?'Confirm batch checkout':'Confirm batch return'}</button>`;
 openForm('Lending & holds',`<form><p class="workspace-kicker">LENDING DESK</p><div class="workspace-intro"><p>Prepare a handover, manage a hold or return a batch of books.</p><span class="badge">${(state.holds||[]).length} active holds</span></div>${nav}<section class="lending-workspace-body">${body}</section>${errorHTML}</form>`,async data=>{
  if(tab==='holds'){await mutate('createHold',data);await lendingTools(tab);}
  else if(tab==='limits'){await mutate('setLendingLimits',{maxBatchCheckout:Number(data.maxBatchCheckout),maxActiveLoans:Number(data.maxActiveLoans)});await lendingTools(tab);}
  else{if(!batchCopies.length)throw Error('Select books to review first.');const count=batchCopies.length;await mutate(tab==='checkout'?'batchCheckout':'batchReturn',{copyIds:[...batchCopies],borrowerId:data.borrowerId||'',checkoutDate:data.checkoutDate||'',dueDate:data.dueDate||'',handoverConfirmed:data.handoverConfirmed==='on'});batchCopies=[];await lendingTools(tab);toast(`${count} books ${tab==='checkout'?'checked out':'returned'}`);}
 });
 $('#form-content').querySelectorAll('[data-lending-tab]').forEach(b=>b.onclick=()=>{batchCopies=[];lendingTools(b.dataset.lendingTab);});
 if(tab==='limits')for(const name of ['maxBatchCheckout','maxActiveLoans']){const field=$(`[name=${name}]`);field.min='1';field.max='100';}
 if(tab==='holds'){
  const action=async(name,id)=>{try{await mutate(name,{holdId:id});await lendingTools('holds');}catch(e){$('.form-error').textContent=e.message;}};
  document.querySelectorAll('[data-hold-ready]').forEach(b=>b.onclick=()=>action('readyHold',b.dataset.holdReady));
  document.querySelectorAll('[data-hold-release]').forEach(b=>b.onclick=()=>{if(confirm('Release this hold? The copy will become available.'))action('releaseHold',b.dataset.holdRelease);});
  document.querySelectorAll('[data-hold-handover]').forEach(b=>b.onclick=()=>{const h=state.holds.find(h=>h.id===b.dataset.holdHandover);if(h.requestId){handOverRequest(h.requestId);return;}openForm('Confirm physical handover',`<form><p>${escape(state.books.find(x=>x.id===h.copyId)?.title||h.copyId)} · ${escape(people.find(x=>x.id===h.borrowerId)?.name||'')}</p>${input('checkoutDate','Handover date',today(),true,'date')}${input('dueDate','Due date (optional)','','','date')}<label><input type="checkbox" name="handoverConfirmed" required> The borrower has received this book.</label>${errorHTML}<button type="submit">Check out held copy</button></form>`,async data=>{await mutate('handoverHold',{...data,holdId:h.id,handoverConfirmed:data.handoverConfirmed==='on'});await lendingTools('holds');});});
 }else if(tab!=='limits'){
  const field=$('[name=batchSearch]');
  function selection(){ $('#batch-selected').innerHTML=batchCopies.map(id=>`<p>${escape(id)} · ${escape(state.books.find(b=>b.id===id)?.title||'')} <button type="button" class="text" data-batch-remove="${escape(id)}">Remove</button></p>`).join('')||'<p>No books selected.</p>';$('#batch-confirm').disabled=!batchCopies.length;document.querySelectorAll('[data-batch-remove]').forEach(b=>b.onclick=()=>{batchCopies=batchCopies.filter(id=>id!==b.dataset.batchRemove);selection();matches();});}
  function add(id){if(batchCopies.includes(id)){$('.form-error').textContent='That physical copy is already in this batch.';return;}if(tab==='checkout'&&batchCopies.length>=(state.maxBatchCheckout||5)){$('.form-error').textContent='This checkout batch has reached its limit.';return;}batchCopies.push(id);field.value='';$('.form-error').textContent='';selection();matches();field.focus();}
  function matches(){const rows=circulationCopies(state,field.value,tab==='return').filter(b=>!batchCopies.includes(b.id));$('#batch-matches').innerHTML=rows.map(b=>`<button type="button" class="secondary" data-batch-add="${escape(b.id)}">Add ${escape(b.id)} · ${escape(b.title)}</button>`).join('')||(field.value?'<p>No eligible copies. Held copies are handled under Holds.</p>':'<p>Scan or search to add the next book.</p>');document.querySelectorAll('[data-batch-add]').forEach(b=>b.onclick=()=>add(b.dataset.batchAdd));}
  field.oninput=matches;$('#batch-scan').onclick=()=>scan(field,'circulation',()=>{const found=circulationCopies(state,field.value,tab==='return').filter(b=>!batchCopies.includes(b.id));if(found.length===1)add(found[0].id);else matches();});selection();matches();
 }
}
$('#lending-tools').onclick=()=>{batchCopies=[];lendingTools();};

async function historyControls(){
 await refresh();if(readOnly)return toast('Reconnect first.');
 const readers=state.readers||[];
 openForm('Clear completed history',`<form><p>Permanent removal from the current library. Active loans, holds, open requests, TBR and currently reading entries stay. Existing backups, exports and other devices may retain older copies; no automatic remote wipe or new pre-clear backup is made.</p><label>Scope<select name="readerId"><option value="all">Entire library history (all readers and guest requests)</option>${readers.map(r=>`<option value="${escape(r.id)}">${escape(r.name)}</option>`).join('')}</select></label><label><input name="reading" type="checkbox" checked> Finished reading, notes and ratings</label><label><input name="loans" type="checkbox"> Returned loans (also removes linked closed requests)</label><label><input name="requests" type="checkbox"> Other closed requests</label>${errorHTML}<button type="submit">Preview removal</button></form>`,async data=>{
 const selection={readerId:data.readerId==='all'?'':data.readerId,allReaders:data.readerId==='all',reading:data.reading==='on',loans:data.loans==='on',requests:data.requests==='on'};
 const preview=await request('/api/history/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(selection)});
 openForm('Confirm history removal',`<form><p>Remove ${preview.reading} finished reading entries, ${preview.loans} returned loans and ${preview.requests} closed requests.</p><p>Keep ${preview.protectedLoans} active loans, ${preview.protectedHolds} holds and ${preview.unfinishedReading} unfinished reading entries. Linked closed requests are removed with returned loans to preserve consistency.</p>${input('confirmation','Type CLEAR HISTORY','',true)}${errorHTML}<button type="submit" class="danger-fill">Clear this history permanently</button></form>`,async data=>{await mutate('clearHistory',{...selection,previewToken:preview.previewToken,confirmation:data.confirmation});$('#form-dialog').close();toast('Selected completed history cleared');});
 });
}
$('#history-controls').onclick=historyControls;

function acquisitionList(){
 const items=[...(state.booksToBuy||[])].sort((a,b)=>a.title.localeCompare(b.title));
 openForm('Books to buy',`<form><p>Your private acquisition wishlist. These books are not owned copies and do not appear in the shared catalog.</p><button type="button" id="wish-add">Scan / add a book</button>${items.length?items.map(x=>`<article class="book"><h3>${escape(x.title)}</h3><p>${escape(x.author)} · ISBN ${escape(x.isbn)}</p>${x.coverUrl?`<img class="cover" src="${escape(x.coverUrl)}" alt="Cover" referrerpolicy="no-referrer">`:''}${googleCredit(x.coverUrl)}<p>${escape(x.notes)}</p><button type="button" data-wish-edit="${escape(x.id)}" class="secondary">Edit</button><button type="button" data-wish-buy="${escape(x.id)}">Acquired — add to library</button><button type="button" data-wish-remove="${escape(x.id)}" class="text danger">Remove from wishlist</button></article>`).join(''):'<p>Your wishlist is empty.</p>'}${errorHTML}</form>`,async()=>{});
 $('#wish-add').onclick=()=>bookForm('',true);
 document.querySelectorAll('[data-wish-edit]').forEach(b=>b.onclick=()=>bookForm(b.dataset.wishEdit,true));
 document.querySelectorAll('[data-wish-remove]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this acquisition wishlist entry?'))return;try{await mutate('removeAcquisition',{id:b.dataset.wishRemove});acquisitionList();}catch(e){$('.form-error').textContent=e.message;}});
 document.querySelectorAll('[data-wish-buy]').forEach(b=>b.onclick=()=>{const item=state.booksToBuy.find(x=>x.id===b.dataset.wishBuy);openForm('Add acquired book',`<form><p>${escape(item.title)} — ${escape(item.author)}</p><label>Collection<select name="collectionId">${state.collections.map(c=>`<option value="${escape(c.id)}">${escape(c.name)}</option>`).join('')}</select></label>${input('room','Room (private)')}${input('bookcase','Bookcase (private)')}${input('shelf','Shelf (private)')}<label><input type="checkbox" name="purchaseConfirmed" required> I now own this physical book</label>${errorHTML}<button type="submit">Add physical copy</button></form>`,async data=>{const duplicates=duplicateBooks(state,item);if(duplicates.length&&!confirm('Possible copies already owned: '+duplicates.map(x=>x.id+' '+x.title).join(', ')+'. Add another physical copy?'))return;const copy=await mutate('acquireBook',{...data,id:item.id,purchaseConfirmed:true,confirmedDuplicates:duplicates.map(x=>x.id)});$('#form-dialog').close();toast('Added '+copy.id+' and removed the wishlist entry.');});});
}
$('#books-to-buy').onclick=async()=>{await refresh();acquisitionList();};

$('#copy-labels').onclick=()=>copyLabels({state,openForm,errorHTML});
$('#copy-numbering').onclick=()=>openForm('Copy numbering',`<form><label>New copy numbers<select name="policy"><option value="fill-gaps" ${state.copyNumberPolicy!=='next-number'?'selected':''}>Fill available gaps</option><option value="next-number" ${state.copyNumberPolicy==='next-number'?'selected':''}>Always use the next number</option></select></label><p>Changes apply to future additions only. Existing books keep their numbers. Numbers still linked to history remain protected. Filling gaps can reuse numbers on old BK-only labels; permanent Carribrary QR labels always identify the original copy.</p>${errorHTML}<button type="submit">Save numbering choice</button></form>`,async input=>{await mutate('setCopyNumberPolicy',input);$('#form-dialog').close();toast('Copy numbering saved');});

$('#sidebar-artwork-settings').onclick=()=>sidebarArtworkSettings({state,mutate,openForm,toast});
$('#dashboard-accounts').onclick=()=>dashboardAccounts({request,openForm,toast});
document.addEventListener('click',e=>{if(e.target.id==='library-artwork')sidebarArtworkSettings({state,mutate,openForm,toast});});

$('#custom-theme').onclick=()=>customThemeEditor({state,mutate,openForm,toast});

async function completeRecoveryGuidance(){
 const companion=location.pathname.startsWith('/companion');
 openForm('Complete Backup Recovery',`<form><h3>Open it on the library server computer</h3><p>Windows: <strong>Start → Carribrary → Complete Backup Recovery</strong> (also available in the tray menu). Approve administrator access.</p><p>Linux/Flatpak: open <strong>Carribrary Complete Backup Recovery</strong> from the application menu, or the Recovery desktop action. On Pi desktop, use the same application-menu entry and approve administrator access.</p>${companion?'':'<p><a class="receipt-open" href="carribrary-recovery:">Open installed recovery wizard</a></p><p>If the browser cannot open that link, use the server’s Start/application menu instead.</p>'}<p>The local wizard verifies a selected .carribrary-backup file, starts a separate test copy, and offers confirmed live restoration only after a successful rehearsal. It keeps current data privately and checks startup. Failed startup attempts an undo; interrupted replacements have a separate Undo option.</p><p>Restore rewinds old passwords, deletions and device revocations. Current connection settings and external Caddy/service configuration stay separate. Recovered email/push settings are paused for review. Windows protected keys may require the original computer.</p><p>Flatpak: use the working dashboard’s authenticated Stop confirmation before replacing live data. Headless Pi: open the bundled recovery launcher over SSH, then use an SSH localhost tunnel to its printed private URL; see Help. No public recovery port or router forwarding.</p><p>Opening this guidance does not stop or restore your server. Phone companions cannot replace the server’s operating-system recovery launcher.</p>${errorHTML}</form>`,async()=>{});
}
async function performSetting(id){
 if(id==='catalog-batch')return catalogBatchEditor({state:{state,revision},openForm,request,scan,refresh,mutate:async(action,input,expected,requestId)=>{const saved=await request('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,input,revision:expected,requestId})});state=validateBackup(saved.state);revision=saved.revision;render();return saved.result;}});
 if(id==='complete-recovery')return completeRecoveryGuidance();
 if(id==='verify-backup')return backupVerification(openForm,escape);
 if(id==='renewals')return renewalSettings({getState:()=>state,openForm,mutate});
 if(id==='rename-library')return editLibraryName();
 if(id==='library-icon')return libraryIconSettings({mutate,openForm,toast});
 if(id==='google-cover-settings')return googleCoverSettings();
 if(id==='push-overview')return notificationOverview();
 if(id==='lending-limits')return lendingTools('limits');
 if(id==='active-loans'){view='loans';render();return;}
 if(id==='household-readers'){view='reading';render();return;}
 if(id==='bulk-edit'){$('#search').value='';view='catalog';selecting=true;render();$('#bulk-bar').scrollIntoView({block:'center'});return;}
 if(id==='share-list'){view='catalog';render();return $('#share-list').onclick();}
 if(id==='import'){openForm('Restore library export',`<form><p>Restore accepts a library JSON export, not a complete encrypted server backup. Review the existing confirmation before replacing records.</p><p class="help">Export a current backup first. Accounts, pairing keys and borrower vaults are not part of this JSON restore.</p><button type="button" id="settings-choose-restore" class="danger-fill">Choose library JSON to review</button>${errorHTML}</form>`,async()=>{});$('#settings-choose-restore').onclick=()=>$('#backup-file').click();return;}
 if(id==='export-csv'){openForm('Export catalog CSV',`<form><p>Download catalog book details for a spreadsheet. Borrower contacts, accounts and private reading data are excluded.</p><button type="button" id="settings-download-csv">Download catalog CSV</button>${errorHTML}</form>`,async()=>{});$('#settings-download-csv').onclick=()=>$('#export-csv').onclick();return;}
 const element=document.getElementById(id);if(!element?.onclick)throw Error('This tool is unavailable. Refresh the library and try again.');return element.onclick.call(element,new Event('click'));
}
document.addEventListener('click',event=>{
 if(view!=='settings'||!event.target.closest('.admin-header')||$('#close-form').disabled)return;
 const button=event.target.closest('button');if(button?.id==='help-button'){event.preventDefault();event.stopImmediatePropagation();location.hash='#settings/system-advanced/help-button';}
 else if(button?.id==='add-book'){event.preventDefault();event.stopImmediatePropagation();view='catalog';render();bookForm();}
},{capture:true});
settingsNavigation=createSettingsNavigation({getState:()=>state,perform:performSetting,onNavigate:()=>{if(view!=='settings')lastNonSettingsView=view;view='settings';render();},onExit:()=>{view=lastNonSettingsView;render();}});
settingsNavigation.start();

document.addEventListener('click',event=>{if(event.target.id!=='complete-recovery-review')return;openForm('Review restored access',`<form><p>Restoring an older snapshot can bring back deleted accounts and revoked devices. Review Borrower accounts, Dashboard administrators, Android phone pairing and iPhone/browser pairing. Revoke or block any access that should remain removed.</p><label><input type="checkbox" name="checked" required> I reviewed the restored accounts and paired devices.</label><label>Type RESUME REMOTE ACCESS<input name="confirmation" autocomplete="off" required></label><p>Recording this review permits the independent recovery wizard to restart the service with normal remote access. Email/push settings remain paused until separately configured.</p>${errorHTML}<button type="submit">Record local review</button></form>`,async input=>{await request('/api/recovery-review/complete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmation:input.confirmation,checked:!!input.checked})});$('#form-dialog').close();toast('Review recorded. Return to Complete Backup Recovery and select Restart after local review.');});});
